const STORAGE_KEY = 'capsule-wardrobe-web-v1';
const asset = (name) => `./assets/clothes/${name}.jpg`;

const seed = [
  {id:'blue-shirt',name:'浅蓝衬衫与领带',category:'上衣',color:'浅蓝',style:['通勤','学院'],season:['春','秋'],keywords:['衬衫','领带','利落'],worn:7,image:asset('white-shirt')},
  {id:'denim-jeans',name:'经典牛仔裤',category:'下装',color:'丹宁蓝',style:['休闲','极简'],season:['春','秋'],keywords:['牛仔','日常','直筒'],worn:4,image:asset('denim-jeans')},
  {id:'brown-bomber',name:'焦糖色飞行夹克',category:'外套',color:'焦糖棕',style:['休闲','复古'],season:['春','秋'],keywords:['夹克','层次','轻外套'],worn:2,image:asset('black-blazer')},
  {id:'evening-dress',name:'莓果色露肩礼服',category:'连衣裙',color:'莓果紫',style:['优雅','派对'],season:['春','夏'],keywords:['约会','礼服','质感'],worn:1,image:asset('satin-dress')},
  {id:'floral-heels',name:'蓝色花卉高跟鞋',category:'鞋子',color:'天蓝',style:['复古','亮点'],season:['春','夏'],keywords:['花卉','高跟','点睛'],worn:8,image:asset('leather-loafers')},
  {id:'check-scarf',name:'格纹围巾',category:'配饰',color:'深灰',style:['温柔','复古'],season:['秋','冬'],keywords:['围巾','保暖','格纹'],worn:0,image:asset('cashmere-scarf')}
];

let state = { clothes: [], selected: [], filters: {category:'',color:'',style:''}, previewImage: '' };
function load(){ try { state.clothes = JSON.parse(localStorage.getItem(STORAGE_KEY)) || structuredClone(seed); } catch { state.clothes = structuredClone(seed); } }
function save(){ localStorage.setItem(STORAGE_KEY, JSON.stringify(state.clothes)); }
function selectedClothes(){ return state.selected.map(id=>state.clothes.find(x=>x.id===id)).filter(Boolean); }
function uniq(field){ return [...new Set(state.clothes.flatMap(x => Array.isArray(x[field]) ? x[field] : [x[field]]))]; }
function esc(str=''){ const node=document.createElement('div'); node.textContent=str; return node.innerHTML; }
function toast(message){ const node=$('#toast'); node.textContent=message; node.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer=setTimeout(()=>node.classList.remove('show'),2200); }
function $(selector){return document.querySelector(selector)}
function $all(selector){return [...document.querySelectorAll(selector)]}

function updateDate(){ const now=new Date(); $('#today-date').textContent=now.toLocaleDateString('zh-CN',{weekday:'long',month:'long',day:'numeric'}).toUpperCase(); }
function renderHome(){ const clothes=state.clothes; $('#nav-count').textContent=clothes.length; const rarely=clothes.filter(x=>!x.worn).length; const styleCount=uniq('style').length; $('#stat-grid').innerHTML=[['衣橱单品',clothes.length],['个人风格',styleCount],['待重新发现',rarely]].map(([label,value])=>`<article class="stat"><b>${value}</b><span>${label}</span></article>`).join(''); $('#recent-grid').innerHTML=clothes.slice(0,3).map(piece=>`<article class="mini-piece"><div class="mini-image" style="background-image:url('${piece.image}')"></div><p>${esc(piece.name)}</p><small>${esc(piece.category)} · ${esc(piece.color)}</small></article>`).join(''); }
function renderChips(id, values, current, key){ $(id).innerHTML=[['','全部'],...values.map(v=>[v,v])].map(([value,label])=>`<button class="chip ${value===current?'active':''}" data-filter="${key}" data-value="${esc(value)}" type="button">${esc(label)}</button>`).join(''); }
function filtered(){ return state.clothes.filter(piece=>Object.entries(state.filters).every(([key,value])=>!value || (Array.isArray(piece[key])?piece[key].includes(value):piece[key]===value))); }
function renderWardrobe(){ renderChips('#category-filters',uniq('category'),state.filters.category,'category');renderChips('#color-filters',uniq('color'),state.filters.color,'color');renderChips('#style-filters',uniq('style'),state.filters.style,'style'); const items=filtered(); $('#wardrobe-summary').textContent=`共 ${state.clothes.length} 件衣物 · 当前显示 ${items.length} 件`; $('#closet-grid').innerHTML=items.map(piece=>`<article class="clothing-card ${state.selected.includes(piece.id)?'selected':''}" data-piece="${piece.id}" tabindex="0" role="button" aria-pressed="${state.selected.includes(piece.id)}"><div class="clothing-image" style="background-image:url('${piece.image}')"></div><span class="select-tick">${state.selected.includes(piece.id)?'✓':''}</span><div class="card-body"><p>${esc(piece.name)}</p><small>${esc(piece.category)} · ${esc(piece.color)}</small></div></article>`).join(''); $('#empty-wardrobe').hidden=items.length>0; $('#selection-bar').hidden=state.selected.length===0; $('#selected-count').textContent=state.selected.length; }
function renderStudio(){ const selected=selectedClothes(); $('#studio-count').textContent=selected.length; $('#studio-selection').innerHTML=selected.map(piece=>`<div class="selected-row"><img src="${piece.image}" alt="${esc(piece.name)}"><p>${esc(piece.name)}<br><small>${esc(piece.category)} · ${esc(piece.color)}</small></p><button type="button" data-remove="${piece.id}" aria-label="移除 ${esc(piece.name)}">×</button></div>`).join(''); $('#selection-help').hidden=selected.length>0; }
function renderAll(){renderHome();renderWardrobe();renderStudio();}
function setView(name){ $all('.view').forEach(node=>node.classList.toggle('active',node.dataset.view===name)); $all('.nav-item').forEach(node=>node.classList.toggle('active',node.dataset.nav===name)); if(location.hash!==`#${name}`) history.replaceState(null,'',`#${name}`); window.scrollTo({top:0,behavior:'smooth'}); }
function togglePiece(id){ state.selected=state.selected.includes(id)?state.selected.filter(x=>x!==id):[...state.selected,id]; renderWardrobe();renderStudio(); }
function chooseComplements(selected){ const priorities=['上衣','下装','外套','鞋子','配饰']; const present=new Set(selected.map(x=>x.category)); const need=priorities.filter(x=>!present.has(x)); const picks=[...selected]; for(const category of need){const match=state.clothes.find(x=>x.category===category&&!picks.some(p=>p.id===x.id));if(match&&picks.length<4)picks.push(match);} return picks.slice(0,4);}
function generateOutfit(){ const locked=selectedClothes(); if(!locked.length){toast('先从衣橱选择至少一件衣物');setView('wardrobe');return;} const mood=$('#mood').value,occasion=$('#occasion').value,keywords=$('#keywords').value.trim(); const clothes=chooseComplements(locked); const missing=clothes.filter(x=>!locked.some(l=>l.id===x.id)); const title=mood==='干练专注'?'利落的城市节奏':mood==='想有一点仪式感'?'轻盈而有光的时刻':mood==='低调舒适'?'安静但有质感':'松弛的日常配方'; const sentence=`以${locked.map(x=>x.name).join('、')}为核心，${missing.length?`加入${missing.map(x=>x.name).join('和')}来平衡比例。`: '保持你已选单品的完整表达。'} ${occasion}场景里，${keywords?`“${keywords}”会成为今天的点睛方向。`:'选择干净的配色和清晰的轮廓，就足够有力量。'}`; $('#outfit-panel').innerHTML=`<article class="outfit-result"><div class="result-intro"><div><p class="eyebrow">YOUR LOOK · ${esc(occasion)}</p><h2>${title}</h2><p>${sentence}</p></div><div class="score">92<br><small>匹配</small></div></div><div class="outfit-pieces">${clothes.map(piece=>`<article class="outfit-piece"><img src="${piece.image}" alt="${esc(piece.name)}"><p>${esc(piece.name)}</p><small>${locked.some(x=>x.id===piece.id)?'已锁定':'建议补充'} · ${esc(piece.category)}</small></article>`).join('')}</div><div class="result-tips"><b>搭配笔记</b><br>保持一处松弛、一处利落的比例。若气温下降，可优先叠加外套；鞋子和包选择相近的深浅，让视觉更完整。</div></article>`; }
function openModal(){ $('#add-modal').hidden=false; document.body.style.overflow='hidden'; $('#add-form [name=name]').focus(); }
function closeModal(){ $('#add-modal').hidden=true; document.body.style.overflow=''; state.previewImage=''; $('#add-form').reset(); $('#upload-preview').innerHTML='＋<small>从相册选择照片</small>'; }
function makeFallback(name,color){ return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 800"><rect width="640" height="800" fill="#ded8ce"/><circle cx="320" cy="310" r="120" fill="#${color.replace('#','')||'b7aaa0'}" opacity=".7"/><text x="50%" y="650" text-anchor="middle" font-family="Arial" font-size="36" fill="#5d574f">${name.slice(0,8)}</text></svg>`)}`;}
function addPiece(event){event.preventDefault();const data=new FormData(event.currentTarget);const name=data.get('name').trim(),color=data.get('color').trim(),style=data.get('style').trim(),category=data.get('category');const item={id:`piece-${Date.now()}`,name,category,color,style:style.split(/[、,，\s]+/).filter(Boolean),season:['春','秋'],keywords:data.get('keywords').split(/[、,，\s]+/).filter(Boolean),worn:0,image:state.previewImage||makeFallback(name,'c8b8a9')};state.clothes.unshift(item);save();closeModal();renderAll();toast('已保存到你的衣橱');setView('wardrobe');}
function reset(){ if(!confirm('确定重置所有本地衣物和搭配数据吗？'))return;state.clothes=structuredClone(seed);state.selected=[];state.filters={category:'',color:'',style:''};localStorage.removeItem(STORAGE_KEY);renderAll();toast('已恢复演示数据');}

document.addEventListener('click',event=>{const button=event.target.closest('button,a');if(!button)return;if(button.dataset.go){event.preventDefault();setView(button.dataset.go)}if(button.dataset.openAdd!==undefined)openModal();if(button.dataset.filter){state.filters[button.dataset.filter]=button.dataset.value;renderWardrobe()}if(button.id==='clear-filters'){state.filters={category:'',color:'',style:''};renderWardrobe()}if(button.id==='clear-selection'){state.selected=[];renderWardrobe();renderStudio()}if(button.id==='send-to-studio'){setView('studio')}if(button.id==='generate-outfit')generateOutfit();if(button.id==='close-modal'||button.id==='cancel-modal')closeModal();if(button.id==='reset-data')reset();if(button.id==='mobile-add')openModal();if(button.dataset.remove){togglePiece(button.dataset.remove)}const card=button.closest('[data-piece]');if(card)togglePiece(card.dataset.piece);});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#add-modal').hidden)closeModal();if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-piece]')){event.preventDefault();togglePiece(event.target.dataset.piece)}});
$('#photo-input').addEventListener('change',event=>{const file=event.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{state.previewImage=reader.result;$('#upload-preview').innerHTML=`<img src="${reader.result}" alt="待上传衣物预览">`};reader.readAsDataURL(file);});
$('#add-form').addEventListener('submit',addPiece);$('#add-modal').addEventListener('click',event=>{if(event.target===$('#add-modal'))closeModal()});
window.addEventListener('hashchange',()=>setView(location.hash.slice(1)||'home'));
load();updateDate();renderAll();setView(location.hash.slice(1)||'home');
